def create_effective_prompt(goal, context, format_type):
    prompt = f"""Goal: {goal}

Context: {context}

Please provide your response in {format_type} format:"""
    return prompt

# Example usage
prompt = create_effective_prompt(
    goal="Explain the benefits of regular exercise",
    context="For middle-aged adults with sedentary lifestyles",
    format_type="bullet points"
)
print(prompt)
